# Этап 1 FACTORIO-01: сведение уроков в свод правил (линии S) и свод без практики (Z). Совет 25.
L_WORDS = 600   # предельная длина свода (слов); Z подгоняется к длине своего S ±10 %
def writer_prompt(prev_rules, episodes):
    """episodes: список dict(id, task, success, measure, lessons, summary) — исходы этого прохода по мере игры (без деталей проверки)"""
    ep = '\n\n'.join(f"[{e['id']}] задача {e['task']}: результат игры — {'УСПЕХ' if e['success'] else 'ПРОВАЛ'}, выпуск после 45 мин без агента {e['measure']:.1f}/мин (квота 16)\n"
                     f"Что построили: {e['summary'][:700]}\nУроки головы: {e['lessons'][:1500]}" for e in episodes)
    prev = f"Твой прежний свод правил:\n-----\n{prev_rules}\n-----\n\n" if prev_rules else ''
    return ("Ты сводишь правила для агентов, которые строят полностью автоматические заводы в Factorio (среда FLE, Python-инструменты). "
            "Ниже — эпизоды твоей линии: что агенты построили, какие уроки записали и что показала игра (выпуск после 45 игровых минут без агента, когда ручные запасы убраны). "
            "Не открывай никаких файлов и не запускай код — работай только по тексту ниже.\n\n" + prev + "Эпизоды этого прохода:\n" + ep +
            f"\n\nНапиши новый свод правил (не больше {L_WORDS} слов): как действовать в этой среде, что работает, чего избегать, какие проверки делать. "
            "Каждое правило — с меткой происхождения в квадратных скобках: id эпизода, где оно родилось, и какую ошибку лечит. Оставляй правило, только если эпизоды его подтверждают; "
            "противоречащее успехам — убери. Пиши общие правила для любых задач этой среды, не рецепт под одну задачу.\nВерни: rules — текст свода; words — число слов.")
def z_prompt(target_words, H='/home/user/neu/experiments/2026-10-06_FACTORIO-01/harness'):
    return ("Ты пишешь свод правил для агентов, которые будут строить полностью автоматические заводы в Factorio (среда FLE, Python-инструменты). "
            f"Сам ты в игру не играешь и опыта в ней не набираешь: прочитай документацию API FLE — файл {H}/FLE_API.md (только его, никаких других файлов, код не запускай) — "
            "и напиши правила из документации и общего знания игры.\n"
            "Условие оценки агентов: после эпизода из сундуков, машин и с лент убирается всё, кроме топлива; завод 45 игровых минут работает сам; засчитывается выпуск ≥ квоты, если всё сырьё и топливо добывают его же буры.\n"
            f"Свод — примерно {target_words} слов (±10 %), правила с короткими пояснениями в квадратных скобках, откуда правило (раздел документации или общее знание). "
            "Пиши общие правила для любых задач этой среды.\nВерни: rules — текст свода; words — число слов.")
SCHEMA_RULES = {'type': 'object', 'properties': {'rules': {'type': 'string'}, 'words': {'type': 'number'}}, 'required': ['rules', 'words']}
